const GLOSSARY = [
 {w:"进攻三区", why:false, d:"场地纵向三等分，最靠近对方球门的 1/3。解说常说「推进到进攻三区」——能不能稳定把球送进这 1/3，是强队的及格线。"},
 {w:"弧顶（为什么总是曼联丢远射？谁保护弧顶？）", why:true, d:"禁区线外那段弧圈，远射高发区，也是攻转守时最容易漏人的地方。<b>负责保护它的通常是 6 号位（后腰）落位兜底</b>；双后腰体系下是两个人的共同责任。曼联被远射，十有八九是攻转守时前场没回位、6 号又被拉走的瞬间。"},
 {w:"半空间 / 肋部", why:false, d:"边线和中路之间的走廊。现代战术的心脏地带：站在这里既能传中又能内切射门，是「又宽又中路」的黄金区。阿莫林让双 10 钻的就是这里，穆西亚拉/维尔茨的杀手本能也长在这里。"},
 {w:"高位 / 中位 / 低位", why:false, d:"防线站位高度。高位 = 压到中圈抢球（巴萨拜仁）；低位 = 缩在禁区前（大巴）。卡里克曼联选择中低位+选择性压迫——把压迫当触发器用，而不是常态。"},
 {w:"高位压迫 / Gegenpress", why:false, d:"丢球后 6 秒内就地反抢。克洛普名言：「Gegenpress 是最好的组织进攻方式」——因为抢下来的地方离球门最近。伊劳拉的利物浦是它的当代样本；克洛普本人 2026 世界杯后接手了德国队。"},
 {w:"转换（Transition）", why:true, d:"攻转守 / 守转攻的瞬间。<b>现代足球大部分进球发生在转换中</b>——所以看球别光看控球，盯「丢球后 5 秒」和「抢断后 5 秒」这两个窗口，你能看到别人看不到的东西。"},
 {w:"造越位陷阱", why:false, d:"防线集体前压，让进攻方接球瞬间越位。高位线的标配，赌的是「我们比你快 0.5 秒」。弗里克巴萨每场造越位 5+ 次。"},
 {w:"三中卫为什么流行？中卫为什么更容易受伤？", why:true, d:"三中卫 = 用中卫横移去覆盖宽度（而非边后卫），<b>中卫的横向冲刺距离大增</b>；叠加现代赛程（一年 60+ 场）和高节奏对抗，中卫群自然成了伤病重灾区。这是负荷问题，不是位置玄学——这也是为什么豪门都要囤 5-6 个中卫。"},
 {w:"左脚中卫 / 右脚中卫", why:false, d:"左中卫配左脚将：向左的出球是顺足，被逼抢时从容（加布里埃尔、巴斯托尼、帕乔、L.马丁内斯、海文、布兰斯维特都是左脚将踢左中卫）。右脚将踢左中卫 = 出球线路整体偏右，对方逼他左侧时只能回传或大脚——可以踢（格瓦迪奥尔、马奎尔都这么踢过），但会被针对性设计。"},
 {w:"双后腰 / 单后腰", why:false, d:"单 6：前面放两个 8，进攻丝滑但弧顶一人保；双 6：保下限，创造力全给前场。豪门往往联赛用单 6、欧冠硬仗用双 6。卡里克曼联用「B费回撤」组成功能不对称的双后腰，巴莱巴到位后可升级为「破坏+组织」标准双后腰。"},
 {w:"定位球为什么突然这么重要？", why:true, d:"英超中游和豪门的分差来源：阵地战破不了密集，就靠角球和长界外球。阿森纳 24-25 靠定位球多拿了 10+ 分，「定位球教练」因此成了豪门标配岗位。"},
 {w:"边路传中的数学期望", why:false, d:"数据结论：英超平均约每 90 次传中才换来 1 个进球——这是卡里克曼联「少传中」改革的依据。传中不是不能用，而是它应该留给「有高中锋+有二点布置」的特定场次，而不是万能解。"},
 {w:"双线间距", why:false, d:"防线与中场线之间的距离。间距小=对手前锋背身拿不到舒服的球（马竞式）；间距大=后场出球空间多但身后危险。看比赛盯「对方前锋站防线和 midfield 之间哪个缝」。"},
 {w:"门将扫荡范围", why:false, d:"清道夫门将敢出到禁区外断球（诺伊尔开创）。拉门斯上季 17 次出击全部成功=扫荡范围大的证据。高位线球队必须配扫荡门将，否则吊射剧本天天上演。"},
 {w:"第二球权 / 转换落位", why:false, d:"射门、传中、解围后的球权争夺。低块球队靠它续命（布伦特福德半数进球是混战），控球球队靠它防止二次进攻。盯人时看「谁在抢第二落点」= 看赛前布置。"},
 {w:"比赛管理（Game Management）", why:false, d:"领先后的时间管理：换人拖时间、边线控球、犯规打断对方节奏。顶级强队 1-0 领先后的 20 分钟射门比是 0-5 但赢球——这就是管理。看曼联领先后的比赛内容，是检验卡里克成色的另一把尺。"},
 {w:"战术犯规的性价比", why:false, d:"对方转换刚发动时在最远处犯规，黄牌换掉一次绝佳反击——现代足球的会计学。瓜系和马竞都把它当常规武器。注意看曼联由攻转守时的第一反应：犯规、回追还是目送？"},
 {w:"中卫出球三选项", why:false, d:"被压迫时中卫只有三个安全出口：短传边后卫（就近）、对角转移（换边）、长传前锋（赌第二落点）。看球时数中卫选了哪条路、为什么——出球中卫和普通中卫的区别就是「选项更少时仍敢选对」。"},
 {w:"锋线联动：9 回撤、10 插上", why:false, d:"支点中锋回撤接球时，身后防线会跟出来——这时候肋部10号/8号斜插他拉出的空间。凯恩回撤+穆西亚拉插上=拜仁的招牌联动；谢什科回撤+库尼亚插上=曼联该有的样子。"},
 {w:"攻防形状（2-3-5 / 4-4-2）", why:true, d:"阵型是「起步姿势」不是站位：进攻时几乎所有豪门都摆 2-3-5，防守时收 4-4-2。<b>判断一支球队看形状，不看名单数字。</b>这条是看懂现代足球的捷径。卡里克曼联 build-up 时的 3-2-5 就是这句话的活教材。"},
 {w:"反越位跑动：时机比速度重要", why:false, d:"打身后的精髓不在冲刺而在<b>启动时机</b>：在对方防线压上的一瞬（长传出脚前）从平行线启动，比快 0.3 秒的纯冲刺更致命。看沃特金斯/伊萨克进球回放：起步那一下都踩在越位线的刀刃上——这就是「用脑子跑出来的单刀」。"},
 {w:"门将手抛球：被低估的快攻发起点", why:false, d:"现代快攻第一传常常不是后卫而是门将的手抛球：落点精准、避开中场绞杀区、直接找边路启动。拉门斯的反击策划、埃德森的对角长传都是武器。看球时数一数：丢球后 10 秒内的快攻，几次是从门将手里开始的？"},
 {w:"安全球哲学：横传回传不是懦弱是算术", why:false, d:"向前传丢 = 直接挨转换反击；向后/横传丢 = 全队还在球附近可以立刻反抢。所以顶级控球队的横传回传占传球 60%+——<b>用低风险传球把对方阵型「磨」变形，等肋部出现 1 秒空当再下刀</b>。骂「倒脚」之前先看丢球位置。"},
 {w:"阵地战节奏变化：忽快忽慢的艺术", why:false, d:"破密集防守的高级玩法：连续 20 脚横传让防线打哈欠，突然一脚直塞提速。匀速围攻防线越站越稳，变速才能把人缝撕开。看巴萨/曼城进球：绝大多数来自「慢-慢-快」的三段式。"},
 {w:"二点进攻布置：弧顶的伏兵", why:false, d:"角球战术不只在禁区内：现代豪门安排专人埋伏弧顶和大禁区线，禁区混战后远射/二次组织。阿森纳的角球得分里近三分之一来自二点。看角球时盯弧顶站谁——那是教练的暗号。"},
 {w:"边中卫内收出球", why:false, d:"build-up 时一名中卫带球或站位内收到后腰位，制造中路人数优势（斯通斯玩法）。代价：中卫离位后防线只剩一条——所以需要「会踢后腰的中卫」。看马兹拉维/斯通斯/阿坎吉的站位图最直观。"},
 {w:"远射的时机学", why:false, d:"远射不是「没招了才射」：它真正的价值是<b>逼迫防线前压</b>——弧顶敢射，对方中卫就必须上提封堵，身后空间就出来了。所以 B费/蒂勒曼斯式的远射型中场是破大巴体系的一环，进球只是 bonus。"},
 {w:"领先后的换人逻辑", why:false, d:"领先换防守型（时间管理）、落后换攻击型（搏命）、平局换「节奏改变者」（换一种进攻方式）。三种换人对应三种比赛状态——看换人先猜意图，再看教练是不是这么干的，你能反推他的比赛计划。"},
 {w:"逆转心理学：丢球后 5 分钟最危险", why:false, d:"数据规律：刚丢球后的 5 分钟是再丢球高发期——心态波动+阵型前压+注意力集中在懊悔上。顶级球队丢球后第一任务是「稳 5 分钟」而不是立刻扳平。看曼联丢球后的下一波攻防，能看出这支球队的心理成熟度。"}
];

